40	export const loader = async ({ request }: LoaderFunctionArgs) => {
41	  const { session } = await authenticate.admin(request);
42	  const shop = session.shop;
43	
44	  let config = await db.widgetConfig.findUnique({ where: { shop } });
45	
46	  if (!config) {
47	    config = await db.widgetConfig.create({ data: { shop } });
48	  }
49	
50	  const subscription = await getShopSubscription(shop);
51	
52	  return { config, subscription };
53	};
