332	// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
333	// Handles @keyframes/@font-face (pass-through), @media (recursive scoping),
334	// and regular selectors (prefixed with container ID).
335	function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
336	  if (!rawCss) return "";
337	  // Sanitize the same way the public API does (mirrors api.widget-config.tsx)
338	  const css = rawCss
339	    .replace(/<style\b[^>]*>/gi, "")
340	    .replace(/<\/style>/gi, "")
341	    .replace(/@import\b[^;]*(;|$)/gi, "")
342	    .replace(/\bexpression\s*\(/gi, "")
343	    .replace(/url\s*\(\s*['"]?\s*javascript\s*:/gi, "url(")
344	    .replace(/url\s*\(\s*['"]?\s*data\s*:/gi, "url(");
345	  let result = "";
346	  let i = 0;
347	  while (i < css.length) {
348	    // Skip whitespace
349	    while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
350	    if (i >= css.length) break;
351	    // Handle at-rules
352	    if (css[i] === "@") {
353	      let atRule = "";
354	      let j = i;
355	      while (j < css.length && css[j] !== "{" && css[j] !== ";") { atRule += css[j]; j++; }
356	      const atName = atRule.trim().toLowerCase();
357	      // @keyframes and @font-face: pass through without scoping
358	      if (atName.startsWith("@keyframes") || atName.startsWith("@font-face")) {
359	        result += atRule;
360	        if (j < css.length && css[j] === "{") {
361	          let depth = 1; result += css[j]; j++;
362	          while (j < css.length && depth > 0) {
363	            if (css[j] === "{") depth++;
364	            if (css[j] === "}") depth--;
365	            result += css[j]; j++;
366	          }
367	        }
368	        i = j; continue;
369	      }
370	      // @media: recursively scope inner rules
371	      if (atName.startsWith("@media")) {
372	        result += atRule;
373	        if (j < css.length && css[j] === "{") {
374	          result += "{"; j++;
375	          let depth = 1; let inner = "";
376	          while (j < css.length && depth > 0) {
377	            if (css[j] === "{") depth++;
378	            if (css[j] === "}") depth--;
379	            if (depth > 0) inner += css[j];
380	            j++;
381	          }
382	          result += scopeAdminCss(inner, wid);
383	          result += "}";
384	        }
385	        i = j; continue;
386	      }
387	    }
388	    // Regular rule: grab selector, prefix with #wid
389	    let sel = "";
390	    let body = "";
391	    while (i < css.length && css[i] !== "{") { sel += css[i]; i++; }
392	    if (i < css.length) i++; // skip {
393	    let depth = 1;
394	    while (i < css.length && depth > 0) {
395	      if (css[i] === "{") depth++;
396	      if (css[i] === "}") depth--;
397	      if (depth > 0) body += css[i];
398	      i++;
399	    }
400	    if (sel.trim()) {
401	      const prefixed = sel.split(",").map(s => {
402	        s = s.trim();
403	        return s ? "#" + wid + " " + s : "";
404	      }).filter(Boolean).join(", ");
405	      result += prefixed + " {" + body + "}";
406	    }
407	  }
408	  return result;
409	}
